<?php
require_once __DIR__ . '/config/config.php';
require_once __DIR__ . '/app/helpers/helpers.php';
require_once __DIR__ . '/config/database.php';
require_auth(); $u=current_user(); if($u['role']!=='talent') redirect('/dashboard.php');
$rows = db()->prepare('SELECT a.*, j.title, j.location, j.modality, c.name company_name FROM applications a JOIN jobs j ON j.id=a.job_id LEFT JOIN companies c ON c.id=j.company_id WHERE a.user_id=? ORDER BY a.created_at DESC'); $rows->execute([$u['id']]); $applications=$rows->fetchAll();
